static void heap_push(int u, long long d) {
    int i = ++heap_size;
    while (i > 1) {
        int p = i / 2;
        if (heap[p].dist <= d) break;
        heap[i] = heap[p];
        i = p;
    }
    heap[i].u = u;
    heap[i].dist = d;
}

static HeapNode heap_pop(void) {
    HeapNode ret = heap[1];
    HeapNode val = heap[heap_size--];
    if (heap_size == 0) return ret;
    int i = 1;
    while (i * 2 <= heap_size) {
        int left = i * 2;
        int right = left + 1;
        int best = left;
        if (right <= heap_size && heap[right].dist < heap[left].dist) {
            best = right;
        }
        if (val.dist <= heap[best].dist) break;
        heap[i] = heap[best];
        i = best;
    }
    heap[i] = val;
    return ret;
}

