    for (int i = 1; i <= total_nodes; i++) {
        dist[i] = INF;
    }

    dist[A] = 0;
    heap_push(A, 0);

    while (heap_size > 0) {
        HeapNode top = heap_pop();
        int u = top.u;
        long long d = top.dist;

        if (d > dist[u]) continue;
        if (u == B) break;

        for (int e = head[u]; e != 0; e = edges[e].next) {
            int v = edges[e].to;
            int w = edges[e].weight;
            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                heap_push(v, dist[v]);
            }
        }
    }

    if (dist[B] >= INF) {
        printf("-1\n");
    } else {
        printf("%lld\n", dist[B]);
    }

    return 0;
}
